import "core-js/modules/es6.function.name";
/*
            一、可监听事件 -- 切换列表与echeart图
            1. 事件 isShowList
            传递给父组件数据 true/false
            2. 事件 getQueryList -- 查询
            传递给父组件数据 {
              statisType 当前选择tabs的类型， day-日报 month-月报 quarter-季报 year-年报 auto-自定义选择
              choiceTime 第一个时间选择框所选择的值
              size 第二个下拉框所选择的值
              quarterQuarter 如果activeName是quarter时，多一个下拉框默认是季度的选择
              userIds 选中人员的id
              }
            二、props传入的参数
            1. showTopFew -- 是否展示选择前五名的下拉框， 默认显示
            2. showUser -- 是否展示选择人员的下拉框，  默认不显示
            3. active -- 开始进入时活动的tab页，  默认day
            4. sizeOptions -- 下拉框的选项，显示前几的    默认显示前5
            5. tabsShow -- tabs显示那些，    默认全部显示
            6. isSelectUserRadio -- 选择人员的下拉框是否是单选 默认不是
              */
import SelectUser from "./selectUser.vue";
import showListOrEcharts from "./showListOrEchart.vue";
import { getTopSelections } from '@/api/workflow/selectUser';
export default {
  name: 'DataPickerTabs',
  components: {
    SelectUser: SelectUser,
    showListOrEcharts: showListOrEcharts
  },
  props: {
    showTopFew: {
      type: Boolean,
      default: true
    },
    // 展示前五名
    showUser: {
      type: Boolean,
      default: false
    },
    // 展示人员组织机构树
    active: {
      type: String,
      default: 'month'
    },
    // 初始进入时，tab页活动页
    sizeOptions: {
      type: Array,
      default: null
    },
    // 第二个下拉坑的选项，默认值前5名
    tabsShow: {
      type: Object,
      default: function _default() {
        return {
          day: true,
          month: true,
          quarter: true,
          year: true,
          auto: true
        };
      }
    },
    // 展示tabs
    isSelectUserRadio: {
      type: Boolean,
      default: false
    },
    // 人员单选
    isShowYear: {
      type: Boolean,
      default: false
    },
    // 日期类型是否为年
    title: {
      type: String,
      default: '参与者'
    },
    // 选择人员的标题
    remarks: {
      type: String,
      default: ''
    },
    setWidth: {
      type: String,
      default: ''
    }
  },
  data: function data() {
    return {
      activeName: 'month',
      dateTimeDay: new Date(),
      dateTimeMonth: new Date(),
      dateTimeQuater: new Date(),
      dateTimeYear: new Date(),
      dateTimeAuto: [new Date(), new Date()],
      value: '5',
      pickerOptions: {
        shortcuts: [{
          text: '今天',
          onClick: function onClick(picker) {
            picker.$emit('pick', [new Date(), new Date()]);
          }
        }, {
          text: '昨天',
          onClick: function onClick(picker) {
            var end = new Date();
            var start = new Date(end.getTime() - 24 * 3600 * 1000);
            picker.$emit('pick', [start, start]);
          }
        }, {
          text: '近7天',
          onClick: function onClick(picker) {
            var end = new Date();
            var start = new Date(end.getTime() - 7 * 24 * 3600 * 1000);
            picker.$emit('pick', [start, end]);
          }
        }, {
          text: '近30天',
          onClick: function onClick(picker) {
            var end = new Date();
            var start = new Date(end.getTime() - 30 * 24 * 3600 * 1000);
            picker.$emit('pick', [start, end]);
          }
        }, {
          text: '本周',
          onClick: function onClick(picker) {
            var current = new Date();
            var currentWeek = current.getDay();
            var start = new Date(current.getTime() - (currentWeek - 1) * 24 * 3600 * 1000);
            var end = new Date(current.getTime() + (7 - currentWeek) * 24 * 3600 * 1000);
            picker.$emit('pick', [start, end]);
          }
        }, {
          text: '本月',
          onClick: function onClick(picker) {
            var current = new Date();
            var year = current.getFullYear();
            var month = current.getMonth() + 1;
            var day = '1';
            var endDays = 30;
            if (month === 1 || month === 3 || month === 5 || month === 7 || month === 8 || month === 10 || month === 12) {
              endDays = 31;
            } else if (month === 2) {
              if (year % 400 === 0 || year % 100 !== 0 && year % 4 === 0) {
                endDays = 29;
              } else {
                endDays = 28;
              }
            }
            var start = new Date("".concat(year, "-").concat(month, "-").concat(day));
            var end = new Date("".concat(year, "-").concat(month, "-").concat(endDays));
            picker.$emit('pick', [start, end]);
          }
        }, {
          text: '上月',
          onClick: function onClick(picker) {
            var date = new Date();
            var year = date.getFullYear();
            var month = date.getMonth();
            if (month === 0) {
              month = 12;
              year = year - 1;
            }
            var startDay = 1;
            var endDays = 30;
            if (month === 1 || month === 3 || month === 5 || month === 7 || month === 8 || month === 10 || month === 12) {
              endDays = 31;
            } else if (month === 2) {
              if (year % 400 === 0 || year % 100 !== 0 && year % 4 === 0) {
                endDays = 29;
              } else {
                endDays = 28;
              }
            }
            picker.$emit('pick', [new Date("".concat(year, "-").concat(month, "-").concat(startDay)), new Date("".concat(year, "-").concat(month, "-").concat(endDays))]);
          }
        }]
      },
      quarterOptions: [{
        value: '0',
        label: '第一季度'
      }, {
        value: '1',
        label: '第二季度'
      }, {
        value: '2',
        label: '第三季度'
      }, {
        value: '3',
        label: '第四季度'
      }],
      quarter: function () {
        var month = new Date().getMonth() + 1;
        if (month < 4) {
          return '0';
        } else if (month < 7) {
          return '1';
        } else if (month < 10) {
          return '2';
        } else {
          return '3';
        }
      }(),
      options: [],
      checked: false,
      users: [{
        id: this.$getHussarUserId(this),
        label: this.$store.state.user.name
      }]
    };
  },
  watch: {
    activeName: {
      handler: function handler() {
        this.queryType();
      },
      deep: true
    },
    users: function users() {
      this.queryType();
    }
  },
  mounted: function mounted() {
    // const this = this;
    this.activeName = this.active;
    this.initSelections();
  },
  methods: {
    updateChecked: function updateChecked(value) {
      this.checked = value;
      this.$emit('isShowList', value);
    },
    clearData: function clearData() {
      if (this.activeName === 'day') {
        this.dateTimeDay = new Date();
      } else if (this.activeName === 'month') {
        this.dateTimeMonth = new Date();
      } else if (this.activeName === 'quarter') {
        this.dateTimeQuater = new Date();
        var month = this.dateTimeQuater.getMonth() + 1;
        if (month < 4) {
          this.quarter = '0';
        } else if (month < 7) {
          this.quarter = '1';
        } else if (month < 10) {
          this.quarter = '2';
        } else {
          this.quarter = '3';
        }
      } else if (this.activeName === 'year') {
        this.dateTimeYear = new Date();
      } else if (this.activeName === 'auto') {
        this.dateTimeAuto = [new Date(), new Date()];
      }
      this.value = '5';
      this.users = [{
        id: this.$getHussarUserId(this),
        label: this.$store.state.user.name
      }];
      this.queryType();
    },
    queryType: function queryType() {
      var params = {};
      params.statisType = this.activeName;
      if (this.activeName === 'day') {
        params.choiceTime = "".concat(this.dateTimeDay.getFullYear(), "-").concat(this.dateTimeDay.getMonth() + 1, "-").concat(this.dateTimeDay.getDate());
      } else if (this.activeName === 'month') {
        params.choiceTime = "".concat(this.dateTimeMonth.getFullYear(), "-").concat(this.dateTimeMonth.getMonth() + 1);
      } else if (this.activeName === 'quarter') {
        params.choiceTime = "".concat(this.dateTimeQuater.getFullYear());
      } else if (this.activeName === 'year') {
        params.choiceTime = "".concat(this.dateTimeYear.getFullYear());
      } else if (this.activeName === 'auto' && this.dateTimeAuto && this.dateTimeAuto.length === 2) {
        params.choiceTime = {
          startTime: "".concat(this.dateTimeAuto[0].getFullYear(), "-").concat(this.dateTimeAuto[0].getMonth() + 1, "-").concat(this.dateTimeAuto[0].getDate()),
          endTime: "".concat(this.dateTimeAuto[1].getFullYear(), "-").concat(this.dateTimeAuto[1].getMonth() + 1, "-").concat(this.dateTimeAuto[1].getDate())
        };
      }
      params.size = this.value;
      params.quarterQuarter = this.quarter;
      params.userIds = this.users.map(function (item) {
        return item.id;
      }).join(',');
      this.$emit('getQueryList', params);
    },
    initSelections: function initSelections() {
      var _this = this;
      // const this = this;
      var params = {
        code: 'statistics_top'
      };
      getTopSelections(params).then(function (res) {
        if (res && res.code && res.code === 10000) {
          _this.options = res.data || [];
        } else {
          _this.$message({
            message: '搜索组织机构失败',
            type: 'error'
          });
        }
      }).catch(function () {
        _this.$message({
          message: '获取字典数据异常',
          type: 'error'
        });
      });
    }
  }
};
